import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
class ActivityTask { const ActivityTask({required this.id, required this.title, required this.minutes, this.done=false}); final String id,title; final int minutes; final bool done; ActivityTask copyWith({bool? done})=>ActivityTask(id:id,title:title,minutes:minutes,done:done??this.done); Map<String,Object> toJson()=>{'id':id,'title':title,'minutes':minutes,'done':done}; factory ActivityTask.fromJson(Map m)=>ActivityTask(id:m['id'] as String? ?? '',title:m['title'] as String? ?? '',minutes:(m['minutes'] as num?)?.toInt()??0,done:m['done']==true); }
class ActivityRepository { ActivityRepository(this.preferences); final SharedPreferences preferences; static const key='activity.tasks.v1'; List<ActivityTask> load(){final raw=preferences.getString(key);if(raw==null)return const [ActivityTask(id:'walk',title:'15 Minuten spazieren gehen',minutes:15)];try{final list=jsonDecode(raw) as List;return list.whereType<Map>().map(ActivityTask.fromJson).toList();}catch(_){return const [];}} Future<void> save(List<ActivityTask> tasks)async{final ok=await preferences.setString(key,jsonEncode(tasks.map((x)=>x.toJson()).toList()));if(!ok)throw StateError('Aktivitäten konnten nicht gespeichert werden.');} }
